const { mc, qcm, vf, ordre, relier, classer, numerique, b, lecon } = require('../dsl');

// Détails des lectures et limites d’alignement : docs/prep-contenus/06-sciences.md.
const originalMeca = { type: 'original', inspireDe: 'INP-HB BAC 2024 (vitesses) ; ESATIC 2024 (mouvements)' };
const rappelsMeca = {
  'MECA-REP': mc('Repère et vecteur', 'Le système est l’objet étudié ; le référentiel est l’objet de référence avec une horloge. Un repère fixe des axes et une origine. Un vecteur possède direction, sens et norme ; ses composantes indiquent ses valeurs signées sur les axes. Les composantes s’ajoutent axe par axe.', 'Convertir les distances en m, les masses en kg et les durées en s.'),
  'MECA-CIN': mc('Position, vitesse, accélération', 'La vitesse moyenne vaut distance/durée. Sur un axe, la vitesse algébrique moyenne vaut variation de position/durée. L’accélération mesure la variation de vitesse par seconde. Si a est constante : v = v₀ + at et x = x₀ + v₀t + ½at².', 'Le signe décrit un sens sur l’axe choisi.'),
  'MECA-NEWTON': mc('Forces et lois de Newton', 'Une force est une interaction, mesurée en newtons. Le poids vaut P = mg. Dans un référentiel galiléen, la résultante des forces extérieures vaut m fois l’accélération. Une résultante nulle conserve la vitesse vectorielle. Les deux forces d’action et réaction concernent deux systèmes différents.', 'Faire le bilan des forces sur un seul système.'),
  'MECA-CHAMP': mc('Mouvement dans un champ uniforme', 'Un champ uniforme garde même direction, même sens et même valeur dans la zone étudiée. Avec le poids seul, a = g vers le bas. Dans un champ électrique uniforme et avec la seule force électrique, a = qE/m en écriture vectorielle. Les coordonnées suivent séparément les lois d’accélération constante.', 'Le signe de la charge et l’orientation des axes comptent.'),
};
const mecaSpec = (notion) => ({ notions: [notion], source: originalMeca, miniCours: rappelsMeca[notion] });
const mecaQuestion = (i, notion, consigne, options, explication) => b.question(qcm({ ...mecaSpec(notion), code: `INPHB-BAC-MECA-L${i}-Q1`, niveau: 1, consigne, options, bonne: 0, explication }));
const mecanique = {
  code: 'INPHB-BAC-MECA', matiere: 'Sciences physiques', titre: 'Mécanique : lois de Newton',
  resume: 'Décrire un mouvement, représenter les forces et appliquer Newton dans les champs de pesanteur et électrique uniformes.',
  notions: [{ code: 'MECA-REP', libelle: 'Unités, référentiels et vecteurs' }, { code: 'MECA-CIN', libelle: 'Position, vitesse et accélération' }, { code: 'MECA-NEWTON', libelle: 'Interactions et lois de Newton' }, { code: 'MECA-CHAMP', libelle: 'Mouvements dans un champ uniforme' }],
  lecons: [
    lecon('INPHB-BAC-MECA-L1', 'Choisir ce que l’on observe', 4, [
      b.texte('Nous allons préciser l’objet étudié et les unités de son mouvement. Dire « il bouge » n’a de sens que par rapport à un repère de référence.'),
      b.texte('Le **système** est l’objet étudié. Le **référentiel** est l’objet de référence auquel on associe une horloge. Un **repère** lui associe une origine O et des axes orientés. Une position sur un axe est une distance signée depuis O : + à droite si l’axe pointe à droite, − à gauche.'),
      b.exemple('Un passager assis', 'Le passager est immobile par rapport au bus, mais se déplace par rapport à la route. Pour étudier le trajet du bus, on choisit généralement le référentiel terrestre lié à la route.'),
      b.tableau(['Grandeur', 'Unité SI'], [['Position ou distance', 'mètre (m)'], ['Durée', 'seconde (s)'], ['Masse', 'kilogramme (kg)']]),
      b.retenir('On utilisera les opérations × (multiplication), / (division) et ² (carré). 1 km = 1 000 m ; 1 h = 3 600 s ; 1 kg = 1 000 g. Une lettre dans une formule représente un nombre avec son unité.'),
      b.piege('La masse se mesure en kg et le poids, qui est une force, en newtons. Une conversion change le nombre, pas la quantité.'),
      mecaQuestion(1, 'MECA-REP', 'Une masse de 500 g vaut…', ['0,5 kg', '500 000 kg', '5 kg'], 'Un kilogramme contient 1 000 g. Donc 500 g = 500/1 000 = 0,5 kg.'),
      b.recap(['Choisir système et référentiel.', 'Fixer origine, axes et horloge.', 'Convertir en m, s et kg.']),
    ]),
    lecon('INPHB-BAC-MECA-L2', 'Lire et additionner des vecteurs', 4, [
      b.texte('Nous allons représenter une grandeur qui possède un sens. Cela servira pour la vitesse et les forces.'),
      b.texte('Une grandeur **scalaire**, comme une masse, est donnée par une valeur et une unité. Un **vecteur**, dessiné par une flèche, possède une direction (la droite support), un sens et une norme (sa longueur représentant sa valeur). On note F⃗ un vecteur force.'),
      b.texte('Une **composante** est la valeur signée sur un axe. Avec x vers la droite et y vers le haut, une flèche horizontale de 3 unités vers la gauche a pour composantes (−3 ; 0). Pour additionner des vecteurs, additionner leurs composantes correspondantes.'),
      b.exemple('Sur le même axe', 'Deux forces de composantes +5 N et −2 N donnent +3 N : leur somme pointe à droite. Le nombre négatif retire une contribution orientée à gauche.'),
      b.exemple('Sur deux axes', 'Les vecteurs (3 ; 0) et (0 ; 4) donnent (3 ; 4). Avec deux axes perpendiculaires, le théorème de Pythagore donne la norme : √(3² + 4²) = √25 = 5. √25 est le nombre positif dont le carré vaut 25.'),
      b.piege('La somme des normes 3 + 4 = 7 n’est pas la norme de la somme de deux vecteurs perpendiculaires.'),
      mecaQuestion(2, 'MECA-REP', 'Sur un axe, +8 N et −3 N donnent une résultante de…', ['+5 N', '+11 N', '−5 N'], 'Les composantes s’ajoutent avec leur signe : 8 + (−3) = 5. Le signe + indique le sens de l’axe.'),
      b.recap(['Direction, sens et norme.', 'Composantes signées.', 'Addition axe par axe.']),
    ]),
    lecon('INPHB-BAC-MECA-L3', 'Calculer une vitesse et son signe', 4, [
      b.texte('Nous allons comparer des déplacements réalisés pendant des durées différentes. La vitesse rend cette comparaison possible.'),
      b.formule('Vitesse moyenne = distance parcourue/durée ; vitesse algébrique moyenne sur x = (x final − x initial)/durée.'),
      b.exemple('Une vitesse moyenne', '500 m parcourus en 60 s donnent 500/60 ≈ 8,33 m/s. Pour obtenir des km/h, multiplier par 3,6, car 1 m/s = 3 600 m/h = 3,6 km/h : on trouve 30 km/h.'),
      b.texte('La **vitesse instantanée** décrit le mouvement à un instant. En mouvement rectiligne uniforme, la trajectoire est droite et la vitesse vectorielle est constante : x(t) = x₀ + vt. x₀ est la position à t = 0.'),
      b.exemple('Un sens négatif', 'x passe de 10 m à 4 m en 2 s, sans retour en arrière. La vitesse algébrique moyenne vaut (4 − 10)/2 = −3 m/s. La valeur de la vitesse est 3 m/s ; le signe − indique le sens opposé à l’axe.'),
      b.piege('Distance parcourue et déplacement signé diffèrent. Sur un aller-retour, la distance est positive même si la position finale est celle du départ.'),
      mecaQuestion(3, 'MECA-CIN', 'À vitesse constante, 120 m en 20 s correspondent à…', ['6 m/s', '2 400 m/s', '0,167 m/s'], 'La vitesse vaut distance/durée : 120/20 = 6 m/s.'),
      b.recap(['Vitesse moyenne : distance/durée.', 'Une vitesse algébrique peut être négative.', 'm/s → km/h : × 3,6.']),
    ]),
    lecon('INPHB-BAC-MECA-L4', 'Décrire une accélération constante', 5, [
      b.texte('Nous allons calculer une vitesse qui change régulièrement. L’accélération décrit cette variation, pas la position.'),
      b.texte('L’**accélération** est la variation de vitesse par durée : a = (v finale − v initiale)/durée si elle est constante. Son unité m/s² signifie « mètre par seconde gagné ou perdu à chaque seconde ».'),
      b.formule('v(t) = v₀ + at ; x(t) = x₀ + v₀t + ½at².', 'v₀ et x₀ sont les valeurs à t = 0 ; a est constante.'),
      b.texte('La première relation ajoute à v₀ une variation at. Avec une accélération constante, la vitesse moyenne algébrique entre 0 et t vaut (v₀ + v(t))/2 : le déplacement vaut donc v₀t + ½at².'),
      b.exemple('Un départ arrêté', 'x₀ = 0, v₀ = 0 et a = 2 m/s². Après 3 s, v = 2 × 3 = 6 m/s et x = 0,5 × 2 × 3² = 9 m.'),
      b.exemple('Un freinage', 'Avec v₀ = +10 m/s et a = −2 m/s², v(3) = 10 − 6 = +4 m/s : le mobile avance encore mais ralentit. Il s’arrête à t = 10/2 = 5 s si cette loi reste valable.'),
      b.piege('Une accélération négative ne signifie pas toujours ralentir : si la vitesse est aussi négative, sa valeur absolue augmente.'),
      mecaQuestion(4, 'MECA-CIN', 'Avec v₀ = 3 m/s et a = 2 m/s², que vaut v à 4 s ?', ['11 m/s', '8 m/s', '20 m/s'], 'Chaque seconde ajoute 2 m/s. En 4 s, la variation vaut 8 m/s ; avec les 3 m/s initiaux, v = 11 m/s.'),
      b.recap(['a mesure la variation de v.', 'Si a constante : v = v₀ + at.', 'Position : ajouter v₀t et ½at² à x₀.']),
    ]),
    lecon('INPHB-BAC-MECA-L5', 'Faire le bilan des forces', 4, [
      b.texte('Nous allons identifier les actions reçues par un objet. Ce bilan permet ensuite d’appliquer les lois de Newton.'),
      b.texte('Une **force** modélise l’action d’un autre objet : elle peut déformer ou modifier le mouvement. Elle se représente par un vecteur et se mesure en newtons (N). Les forces **extérieures** viennent d’objets hors du système choisi.'),
      b.liste(['Le poids P⃗ : attraction de la Terre, vertical vers le bas ; sa norme vaut P = mg, avec g ≈ 9,8 N/kg près du sol.', 'La réaction normale : action d’un support perpendiculaire à sa surface.', 'Le frottement : action tangentielle qui s’oppose au glissement relatif ; la tension d’un fil tire selon le fil.']),
      b.exemple('Un livre posé', 'Le livre reçoit son poids vers le bas et l’action normale de la table vers le haut. Pour m = 0,5 kg et g = 10 N/kg, son poids vaut 0,5 × 10 = 5 N.'),
      b.retenir('Troisième loi de Newton : si A agit sur B, B agit sur A avec une force opposée de même norme. Ces deux forces s’appliquent à deux objets différents.'),
      b.piege('Dans le bilan du livre, on compte la force de la table sur le livre, pas la force du livre sur la table. Elles ne s’annulent pas dans le bilan d’un même objet.'),
      mecaQuestion(5, 'MECA-NEWTON', 'Quelle force inclure dans le bilan d’un livre posé sur une table ?', ['L’action de la table sur le livre', 'L’action du livre sur la table', 'Le poids de la table'], 'Le système est le livre. On conserve les forces qu’il reçoit, dont l’action de la table ; les actions qu’il exerce appartiennent à d’autres bilans.'),
      b.recap(['Choisir un seul système.', 'Lister ce qu’il reçoit.', 'Action-réaction : objets différents.']),
    ]),
    lecon('INPHB-BAC-MECA-L6', 'L’inertie : conserver son mouvement', 4, [
      b.texte('Nous allons comprendre pourquoi une force n’est pas nécessaire pour entretenir une vitesse constante dans le modèle sans frottement.'),
      b.texte('Un **référentiel galiléen** est un référentiel où le principe d’inertie s’applique. Pour les expériences courtes près du sol, on assimile souvent le référentiel terrestre à un référentiel galiléen.'),
      b.retenir('Première loi de Newton : si la somme vectorielle des forces extérieures est nulle, le système reste au repos ou en mouvement rectiligne uniforme. Sa vitesse vectorielle ne change pas.'),
      b.exemple('Un palet idéal', 'Sur un plan horizontal sans frottement, poids et réaction normale se compensent. Après la poussée initiale, le palet conserve sa vitesse en ligne droite, même sans force horizontale.'),
      b.exemple('Un livre immobile', 'Sa vitesse reste nulle. Sur la verticale, le poids vers le bas et la réaction vers le haut ont alors même norme et somme nulle.'),
      b.piege('Somme nulle ne veut pas dire absence de forces. Et une vitesse de norme constante sur un cercle change de direction : ce n’est pas un mouvement rectiligne uniforme.'),
      mecaQuestion(6, 'MECA-NEWTON', 'La somme des forces est nulle dans un référentiel galiléen. Le mobile peut-il avancer ?', ['Oui, à vitesse vectorielle constante', 'Non, il doit forcément être immobile', 'Oui, en accélérant continuellement'], 'Une résultante nulle impose la conservation de la vitesse vectorielle, qui peut être nulle ou non. Elle n’impose pas le repos.'),
      b.recap(['Résultante nulle → vitesse vectorielle constante.', 'Repos et mouvement rectiligne uniforme sont possibles.', 'Préciser le référentiel.']),
    ]),
    lecon('INPHB-BAC-MECA-L7', 'Relier résultante et accélération', 4, [
      b.texte('Nous allons calculer la variation du mouvement à partir des forces. C’est la deuxième loi de Newton.'),
      b.formule('ΣF⃗ extérieures = m a⃗ ; sur un axe : ΣFₓ = maₓ.', 'Σ signifie somme ; masse constante en kg, forces en N, accélération en m/s² ; référentiel galiléen.'),
      b.texte('La **résultante** est la somme vectorielle des forces reçues. On choisit un axe, on écrit les composantes avec leur signe puis on divise la résultante par la masse.'),
      b.exemple('Traction avec frottement', 'Un bloc de 2 kg reçoit 10 N vers la droite et 4 N vers la gauche. Sur x orienté à droite : 10 − 4 = 2aₓ, donc aₓ = 6/2 = 3 m/s².'),
      b.exemple('Masse doublée', 'Avec la même résultante de 6 N mais une masse de 4 kg, a = 6/4 = 1,5 m/s². Une même action change moins vite la vitesse d’une masse plus grande.'),
      b.piege('Utiliser la résultante, pas seulement la force motrice. Une vitesse initiale n’entre pas dans ΣF = ma ; elle sert ensuite à trouver v(t).'),
      mecaQuestion(7, 'MECA-NEWTON', 'Une résultante de 12 N agit sur 3 kg. Quelle accélération produit-elle ?', ['4 m/s²', '36 m/s²', '0,25 m/s²'], 'La relation F = ma donne a = F/m = 12/3 = 4 m/s², dans le sens de la résultante.'),
      b.recap(['Bilan des forces → somme signée.', 'a = résultante/masse.', 'Puis utiliser les lois du mouvement.']),
    ]),
    lecon('INPHB-BAC-MECA-L8', 'La chute libre sur un axe vertical', 4, [
      b.texte('Nous allons prévoir une chute quand le poids est la seule force retenue. Cette hypothèse exclut la résistance de l’air et la poussée d’Archimède.'),
      b.texte('Près du sol, le **champ de pesanteur uniforme** garde la même valeur g et pointe vers le bas. Newton donne ma⃗ = mg⃗, donc a⃗ = g⃗ : la masse se simplifie. Dans ce modèle, l’accélération de chute est indépendante de la masse.'),
      b.formule('Axe z vers le haut : a_z = −g ; v_z = v₀z − gt ; z = z₀ + v₀z t − ½gt².'),
      b.exemple('Lâcher sans vitesse', 'z₀ = 20 m, v₀z = 0 et g = 10 m/s². Après 1 s, v_z = −10 m/s et z = 20 − 5 = 15 m. Pour atteindre le sol z = 0 : 5t² = 20, donc t² = 4 et t = 2 s.'),
      b.exemple('Lancer vers le haut', 'Avec v₀z = +20 m/s et g = 10, le sommet est atteint quand v_z = 0 : 20 − 10t = 0 donne t = 2 s. L’accélération reste −10 m/s², même au sommet.'),
      b.piege('Vitesse nulle au sommet ne signifie pas accélération nulle. Choisir le signe de g après avoir orienté l’axe.'),
      mecaQuestion(8, 'MECA-CHAMP', 'Au sommet d’un lancer vertical sans frottement, quelle force reste présente ?', ['Le poids', 'Aucune force', 'Une force de lancement persistante'], 'Le contact du lanceur est terminé. Le poids continue d’agir pendant toute la trajectoire, y compris quand la vitesse est instantanément nulle.'),
      b.recap(['Poids seul → accélération g vers le bas.', 'Axe vers le haut : a_z = −g.', 'Une durée physique est positive.']),
    ]),
    lecon('INPHB-BAC-MECA-L9', 'Séparer les axes d’un projectile', 5, [
      b.texte('Nous allons décomposer un lancer en mouvement horizontal et mouvement vertical. Les deux coordonnées utilisent le même temps.'),
      b.texte('On néglige l’air. Avec x horizontal et z vers le haut, le poids n’a pas de composante horizontale : aₓ = 0 et a_z = −g. Les composantes initiales v₀x et v₀z sont les parts horizontale et verticale de la vitesse.'),
      b.formule('x = x₀ + v₀x t ; z = z₀ + v₀z t − ½gt².'),
      b.exemple('Un lancer depuis le sol', 'On donne x₀ = z₀ = 0, v₀x = 6 m/s, v₀z = 8 m/s et g = 10. Alors x = 6t et z = 8t − 5t². Au sol, z = 0. On met t en facteur : 8t − 5t² = t(8 − 5t). Un produit est nul si au moins un facteur est nul. On exclut le départ t = 0 ; 8 − 5t = 0 donne 5t = 8, donc t = 1,6 s. La portée est x = 6 × 1,6 = 9,6 m.'),
      b.texte('Si l’angle α est mesuré depuis l’horizontale, v₀x = v₀ cos α et v₀z = v₀ sin α. Dans le triangle rectangle des composantes, cos α est côté horizontal/hypoténuse et sin α côté vertical/hypoténuse. Un angle depuis la verticale échange ces rôles.'),
      b.exemple('Équation de trajectoire', 'Pour le même lancer, t = x/6. Remplacer dans z donne z = 8x/6 − 5x²/36 : c’est une parabole, courbe où apparaît un terme en x².'),
      b.piege('Ne pas prendre le temps horizontal et le temps vertical comme deux durées indépendantes : c’est le même objet au même instant.'),
      mecaQuestion(9, 'MECA-CHAMP', 'Sans air, quelle composante de la vitesse reste constante pendant ce lancer ?', ['La composante horizontale', 'La composante verticale', 'Les deux composantes'], 'La résultante horizontale est nulle, donc aₓ = 0 et vₓ reste constante. Sur la verticale, le poids modifie v_z.'),
      b.recap(['Un seul temps pour les deux axes.', 'Horizontal : vitesse constante.', 'Vertical : accélération −g ; portée au retour au sol.']),
    ]),
    lecon('INPHB-BAC-MECA-L10', 'Une particule dans un champ électrique uniforme', 5, [
      b.texte('Nous allons appliquer la même méthode à une particule chargée. La différence vient de la force et du signe de la charge.'),
      b.texte('La **charge électrique** q, positive ou négative, se mesure en coulombs (C). Le **champ électrique** E⃗ représente la force par coulomb : F⃗ électrique = qE⃗. Dans un champ uniforme, E⃗ est constant. On néglige ici poids et autres forces.'),
      b.formule('a⃗ = qE⃗/m.', 'E en N/C, q en C, m en kg ; une charge négative accélère à l’opposé du champ.'),
      b.exemple('Le signe de la déviation', 'E⃗ pointe vers le haut. Une charge positive accélère vers le haut ; une charge négative accélère vers le bas. Il faut donc lire le signe de q avant de dessiner la trajectoire.'),
      b.exemple('Un calcul sur un axe', 'q = +0,000002 C, E_y = +100 N/C, m = 0,000001 kg : a_y = 0,000002 × 100/0,000001 = +200 m/s². Si v₀y = y₀ = 0, après 0,01 s, y = 0,5 × 200 × 0,01² = 0,01 m.'),
      b.piege('Le signe de q change le sens de la force, pas la direction du champ imposé. La masse est toujours positive.'),
      mecaQuestion(10, 'MECA-CHAMP', 'Une charge négative est soumise à un champ électrique vers la droite. Sa force électrique pointe…', ['Vers la gauche', 'Vers la droite', 'Toujours vers le bas'], 'F⃗ = qE⃗. Multiplier un vecteur par un nombre négatif inverse son sens : la force pointe donc à gauche.'),
      b.recap(['Champ uniforme → force électrique constante.', 'F⃗ = qE⃗ puis a⃗ = qE⃗/m.', 'Même méthode cinématique, attention au signe de q.']),
    ]),
  ],
  exercices: [
    relier({ ...mecaSpec('MECA-REP'), code: 'INPHB-BAC-MECA-E01', niveau: 1, consigne: 'Relie chaque grandeur à son unité SI.', paires: [['Masse', 'kg'], ['Distance', 'm'], ['Durée', 's']], explication: 'On associe la quantité de matière au kilogramme, la distance au mètre et la durée à la seconde. Ces unités doivent être utilisées ensemble dans les calculs de Newton.' }),
    numerique({ ...mecaSpec('MECA-REP'), code: 'INPHB-BAC-MECA-E02', niveau: 1, consigne: 'Sur un axe positif vers la droite, deux forces ont les composantes +7 N et −2 N. Donne la composante de leur somme.', valeur: 5, unite: 'N', explication: 'La somme se fait avec les signes : +7 + (−2) = +5 N. La résultante est donc dirigée vers la droite.' }),
    qcm({ ...mecaSpec('MECA-CIN'), code: 'INPHB-BAC-MECA-E03', niveau: 1, consigne: 'Qui est le plus rapide : Bari à 10 km/h, Binaté à 500 m/min, Cissé à 8 km/h, ou Ben à 300 m/min ?', options: ['Binaté', 'Bari', 'Cissé', 'Ben'], bonne: 0, source: { type: 'annale', organisme: 'INP-HB', annee: 2024, epreuve: 'Test de niveau BAC, culture scientifique, Q43 (adaptation)', documentId: '6ad9c9c036b1c50cc9403b37' }, explication: '(INP-HB 2024, culture scientifique, Q43) On met toutes les vitesses en km/h. Binaté : 500 × 60/1 000 = 30 km/h. Ben : 300 × 60/1 000 = 18 km/h. Les deux autres valent 10 et 8 km/h. Le maximum est 30 km/h : Binaté.' }),
    numerique({ ...mecaSpec('MECA-CIN'), code: 'INPHB-BAC-MECA-E04', niveau: 1, consigne: 'La vitesse passe de 2 m/s à 10 m/s en 4 s, avec accélération constante. Calcule cette accélération.', valeur: 2, unite: 'm/s²', explication: 'La variation de vitesse est 10 − 2 = 8 m/s. On la divise par la durée : a = 8/4 = 2 m/s².' }),
    qcm({ ...mecaSpec('MECA-NEWTON'), code: 'INPHB-BAC-MECA-E05', niveau: 1, consigne: 'Le système est un livre posé sur une table. Quelle paire constitue les deux forces reçues dans le modèle simple ?', options: ['Poids du livre et réaction de la table sur le livre', 'Poids de la table et force du livre sur la table', 'Force du livre sur la Terre et poids de la table'], bonne: 0, explication: 'On conserve seulement les actions reçues par le livre : celle de la Terre, son poids, et celle du support. Les actions qu’il exerce sur la table ou la Terre ne figurent pas dans son bilan.' }),
    vf({ ...mecaSpec('MECA-NEWTON'), code: 'INPHB-BAC-MECA-E06', niveau: 2, consigne: 'Juge dans un référentiel galiléen.', affirmations: [['Une résultante nulle impose toujours le repos.', false], ['Action et réaction agissent sur deux systèmes différents.', true], ['Une vitesse vectorielle constante implique une accélération nulle.', true]], explication: 'Une résultante nulle conserve la vitesse, qui peut être non nulle : la première est fausse. L’action-réaction relie deux objets distincts : la deuxième est vraie. Si la vitesse vectorielle ne change pas, sa variation est nulle, donc l’accélération aussi : la troisième est vraie.' }),
    numerique({ ...mecaSpec('MECA-NEWTON'), code: 'INPHB-BAC-MECA-E07', niveau: 2, consigne: 'Un bloc de 2 kg est tiré par 10 N vers la droite ; un frottement de 4 N s’y oppose. Calcule aₓ, axe vers la droite.', valeur: 3, unite: 'm/s²', explication: 'La somme horizontale est 10 − 4 = 6 N. Newton donne 6 = 2aₓ ; en divisant par 2, on obtient aₓ = 3 m/s².' }),
    numerique({ ...mecaSpec('MECA-CIN'), code: 'INPHB-BAC-MECA-E08', niveau: 2, consigne: 'Un mobile part de x₀ = 0 avec v₀ = 3 m/s et a = 2 m/s² constante. Calcule x après 4 s.', valeur: 28, unite: 'm', explication: 'On utilise x = x₀ + v₀t + ½at². Le terme de vitesse initiale vaut 3 × 4 = 12 m. Le terme d’accélération vaut 0,5 × 2 × 4² = 16 m. Total : x = 28 m.' }),
    numerique({ ...mecaSpec('MECA-CHAMP'), code: 'INPHB-BAC-MECA-E09', niveau: 2, consigne: 'Un objet est lâché sans vitesse à 20 m du sol. Poids seul, g = 10 m/s². Combien de secondes avant de toucher le sol ?', valeur: 2, unite: 's', explication: 'Avec z vers le haut, z = 20 − 5t². Au sol z = 0, donc 5t² = 20 puis t² = 4. La durée étant positive, t = 2 s.' }),
    qcm({ ...mecaSpec('MECA-CHAMP'), code: 'INPHB-BAC-MECA-E10', niveau: 2, consigne: 'Une charge négative entre horizontalement dans un champ électrique uniforme dirigé vers le haut. On néglige les autres forces. Sa déviation est…', options: ['Vers le bas', 'Vers le haut', 'Nulle'], bonne: 0, explication: 'La force vaut qE⃗. Comme q < 0, elle pointe à l’opposé du champ, donc vers le bas. L’accélération est dans le même sens que cette force et la trajectoire se courbe vers le bas.' }),
    numerique({ ...mecaSpec('MECA-CIN'), code: 'INPHB-BAC-MECA-E11', niveau: 3, consigne: 'Un coureur termine 10 000 m en 31 min 20 s. Les 10 premiers tours de 400 m ont duré 13 min 20 s. Quelle vitesse moyenne en km/h sur les 15 derniers tours ?', valeur: 20, unite: 'km/h', source: { type: 'annale', organisme: 'INP-HB', annee: 2024, epreuve: 'Test de niveau BAC, culture scientifique, Q55 (adaptation)', documentId: '6ad9c9c036b1c50cc9403b37' }, explication: '(INP-HB 2024, culture scientifique, Q55) Les 15 derniers tours représentent 15 × 400 = 6 000 m = 6 km. Leur durée est 31 min 20 s − 13 min 20 s = 18 min = 18/60 = 0,3 h. La vitesse moyenne est 6/0,3 = 20 km/h.' }),
    numerique({ ...mecaSpec('MECA-NEWTON'), code: 'INPHB-BAC-MECA-E12', niveau: 3, consigne: 'Un mobile de 500 g suit x(t) = 2t² − 3t + 1, en m et s. Pour t > 0,75 s, il avance vers +x, sous une force motrice vers +x et un frottement de 2 N vers −x. Calcule la force motrice.', valeur: 4, unite: 'N', source: { type: 'annale', organisme: 'ESATIC', annee: 2024, epreuve: 'Physique, Q21 (adaptation précisant le sens du mouvement)', documentId: '6ac01ecf36d8963a0a88c481' }, explication: '(ESATIC 2024, physique, Q21) Comparer x = 1 − 3t + 2t² à x₀ + v₀t + ½at² donne ½a = 2, donc a = 4 m/s². Convertir 500 g en 0,5 kg. Newton donne F motrice − 2 = 0,5 × 4 = 2 N ; donc F motrice = 4 N.', indice: 'Le coefficient de t² est ½a, pas a.' }),
    numerique({ ...mecaSpec('MECA-CHAMP'), code: 'INPHB-BAC-MECA-E13', niveau: 3, consigne: 'Un projectile part du sol avec v₀x = 6 m/s et v₀z = 8 m/s. Poids seul, g = 10 m/s². Quelle portée horizontale au retour au sol ?', valeur: 9.6, unite: 'm', explication: 'La coordonnée verticale vaut z = 8t − 5t². Au retour au sol, t > 0 et t(8 − 5t) = 0 donne t = 1,6 s. Horizontalement x = 6t, donc la portée vaut 6 × 1,6 = 9,6 m.' }),
    numerique({ ...mecaSpec('MECA-CHAMP'), code: 'INPHB-BAC-MECA-E14', niveau: 3, consigne: 'Une particule de charge q = −2 µC et de masse 1 mg subit uniquement un champ E_y = +100 N/C. Calcule a_y en m/s².', valeur: -200, unite: 'm/s²', explication: 'q = −0,000002 C et 1 mg = 0,000001 kg. F_y = qE_y = −0,0002 N. Alors a_y = F_y/m = −0,0002/0,000001 = −200 m/s². Le signe − traduit une accélération opposée au champ.' }),
  ],
};


const originalOndes = { type: 'original', inspireDe: 'ESATIC 2023–2024, physique (circuits, oscillations et diffraction)' };
const rappelsOndes = {
  'ONDE-PROP': mc('Propagation d’une perturbation', 'Une onde transporte une perturbation et de l’énergie sans transport global de matière. Une onde mécanique exige un milieu matériel. Sa célérité c vaut distance/durée de propagation ; le retard entre deux points distants de d vaut d/c. La fréquence est fixée par la source.', 'Distinguer déplacement de la perturbation et mouvement local du milieu.'),
  'ONDE-PER': mc('Période, fréquence et longueur d’onde', 'La période T est la durée d’un cycle ; la fréquence f compte les cycles par seconde, en hertz : f = 1/T. La longueur d’onde λ est la distance parcourue par l’onde pendant une période : λ = cT = c/f. Pour une sinusoïde centrée sur zéro, l’amplitude est la valeur maximale positive, pas la valeur crête à crête.', 'T en s, c en m/s, λ en m.'),
  'ONDE-DIFF': mc('Diffraction par une fente', 'La diffraction étale une onde après une ouverture. Elle devient marquée quand la largeur de l’ouverture est comparable à la longueur d’onde. Pour la lumière monochromatique et une fente de largeur a, à petits angles : θ ≈ λ/a ; sur un écran éloigné de D, la largeur centrale entre les deux premiers minima vaut L ≈ 2Dλ/a.', 'Réduire a élargit la tache centrale.'),
  'ONDE-LC': mc('Oscillations électriques libres', 'Un condensateur stocke ½Cu² ; une bobine idéale d’inductance L stocke ½Li². Dans un circuit LC idéal isolé, l’énergie s’échange sans perte et la période propre est T₀ = 2π√(LC). La résistance d’un circuit réel dissipe de l’énergie et amortit les oscillations, quand elles existent.', 'L en henrys, C en farads ; T₀ en secondes.'),
  'ONDE-RLC': mc('Amortissement et excitation', 'Une résistance dissipe de l’énergie par effet Joule. Dans un RLC libre faiblement amorti, les oscillations diminuent ; un amortissement fort peut supprimer les oscillations. Un générateur périodique impose sa fréquence au régime forcé établi. Dans un RLC série idéal, le courant est maximal à f₀ = 1/(2π√(LC)). L’impédance Z = U efficace/I efficace vaut alors R. Pour une sinusoïde, valeur efficace = amplitude/√2.', 'Oscillation libre : fréquence propre ; régime forcé établi : fréquence du générateur.'),
};
const ondeSpec = (notion) => ({ notions: [notion], source: originalOndes, miniCours: rappelsOndes[notion] });
const ondeQuestion = (i, notion, consigne, options, explication) => b.question(qcm({ ...ondeSpec(notion), code: `ESATIC-BAC-ONDES-L${i}-Q1`, niveau: 1, consigne, options, bonne: 0, explication }));
const ondes = {
  code: 'ESATIC-BAC-ONDES', matiere: 'Sciences physiques', titre: 'Ondes et signaux',
  resume: 'Propagation, retards, signaux périodiques et diffraction, puis échanges d’énergie LC et oscillations RLC.',
  notions: [{ code: 'ONDE-PROP', libelle: 'Ondes mécaniques, célérité et retard' }, { code: 'ONDE-PER', libelle: 'Période, fréquence, longueur d’onde et sinusoïde' }, { code: 'ONDE-DIFF', libelle: 'Diffraction par une fente' }, { code: 'ONDE-LC', libelle: 'Énergie et période d’un oscillateur LC' }, { code: 'ONDE-RLC', libelle: 'Amortissement et oscillations forcées' }],
  lecons: [
    lecon('ESATIC-BAC-ONDES-L1', 'Une perturbation qui se propage', 4, [
      b.texte('Nous allons distinguer l’avancée d’une onde du mouvement de la matière. Ce parcours utilise les unités et les condensateurs étudiés dans PC-ELEC ; les relations nécessaires seront rappelées.'),
      b.texte('Une **perturbation** est une modification locale d’un état, comme soulever un point d’une corde. Une **onde progressive** est la propagation de cette perturbation. Elle transporte de l’énergie sans déplacement global de matière. Une onde **mécanique** nécessite un milieu matériel.'),
      b.exemple('Une corde', 'Une impulsion fait monter puis redescendre chaque morceau de corde. La bosse avance le long de la corde, mais les morceaux de corde ne voyagent pas avec elle.'),
      b.texte('Une onde est **transversale** si le mouvement local est perpendiculaire à la propagation ; elle est **longitudinale** s’il est parallèle. Le son dans l’air est une succession de compressions longitudinales.'),
      b.exemple('Deux familles', 'Le son a besoin d’air ou d’un autre milieu. La lumière est une onde électromagnétique qui peut se propager dans le vide : elle n’est pas mécanique.'),
      b.piege('Confondre onde et vent : le vent déplace globalement l’air ; une onde sonore fait surtout osciller l’air localement.'),
      ondeQuestion(1, 'ONDE-PROP', 'Pourquoi le son ne se propage-t-il pas dans le vide ?', ['Il a besoin d’un milieu matériel', 'Sa fréquence y devient nulle', 'La lumière l’empêche de passer'], 'Le son est mécanique : des particules transmettent des compressions à leurs voisines. Dans le vide, ce milieu matériel manque.'),
      b.recap(['Onde : propagation d’une perturbation.', 'Pas de transport global de matière.', 'Mécanique : milieu nécessaire.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L2', 'Célérité et retard', 4, [
      b.texte('Nous allons calculer quand une perturbation arrive à un point. Sa vitesse de propagation s’appelle la célérité.'),
      b.formule('c = d/Δt ; retard Δt = d/c.', 'c en m/s, distance d en m, durée Δt en s ; Δ se lit « variation ».'),
      b.exemple('Sur une corde', 'Une bosse parcourt 6 m en 2 s. Sa célérité vaut 6/2 = 3 m/s. Deux points distants de 1,5 m reçoivent la même bosse avec un retard de 1,5/3 = 0,5 s.'),
      b.texte('Dans le modèle sans déformation ni atténuation, le signal au second point est le même, reçu plus tard. La célérité dépend du milieu et de ses conditions ; elle ne doit pas être confondue avec la vitesse d’un point qui oscille.'),
      b.exemple('Un écho', 'Un son parcourt l’aller jusqu’à l’obstacle et le retour. Si c = 340 m/s et si l’écho revient après 0,2 s, le trajet total vaut 68 m ; l’obstacle est à 68/2 = 34 m.'),
      b.piege('Pour un écho, d dans c = d/Δt est le trajet aller-retour, pas seulement la distance de l’obstacle.'),
      ondeQuestion(2, 'ONDE-PROP', 'Une onde de célérité 4 m/s parcourt 2 m. Quel est le retard ?', ['0,5 s', '8 s', '2 s'], 'Le retard vaut d/c = 2/4 = 0,5 s.'),
      b.recap(['Célérité = distance/durée.', 'Retard = distance/célérité.', 'Écho : tenir compte des deux trajets.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L3', 'Compter des cycles : période et fréquence', 4, [
      b.texte('Nous allons mesurer la répétition d’un signal. Cela sert aussi bien pour une vibration que pour une tension électrique.'),
      b.texte('Un **signal** est une grandeur qui porte une information, par exemple une tension en fonction du temps. Il est **périodique** s’il se répète identiquement après une durée T appelée période. La **fréquence** f compte le nombre de cycles par seconde ; son unité est le hertz (Hz).'),
      b.formule('f = 1/T ; T = 1/f ; si N cycles durent Δt, T = Δt/N.'),
      b.exemple('Dix cycles observés', 'Dix cycles en 0,2 s donnent T = 0,2/10 = 0,02 s. La fréquence vaut 1/0,02 = 50 Hz.'),
      b.exemple('Lire un graphe', 'Sur une courbe en fonction du temps, deux maxima successifs identiques sont à 3 ms et 8 ms. La période est 8 − 3 = 5 ms = 0,005 s, donc f = 200 Hz.'),
      b.piege('Un cycle comprend un retour au même état, avec le même sens de variation. Entre deux passages par zéro de sens opposés, il peut ne s’écouler qu’une demi-période.'),
      ondeQuestion(3, 'ONDE-PER', 'Une période de 0,01 s correspond à quelle fréquence ?', ['100 Hz', '0,01 Hz', '10 Hz'], 'La fréquence est l’inverse de la période : 1/0,01 = 100 cycles par seconde, soit 100 Hz.'),
      b.recap(['Période : durée d’un cycle.', 'Fréquence : cycles par seconde.', 'Convertir les ms en s avant f = 1/T.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L4', 'La longueur d’onde : une période dans l’espace', 4, [
      b.texte('Nous allons relier la répétition dans le temps à la répétition dans l’espace. La longueur d’onde rend ce lien visible.'),
      b.texte('La **longueur d’onde** λ, lettre grecque lambda, est la distance parcourue pendant une période. À un instant donné, deux crêtes successives d’une onde sinusoïdale sont séparées par λ.'),
      b.formule('λ = cT = c/f.', 'λ en m ; c en m/s ; T en s ; f en Hz.'),
      b.exemple('Des vagues régulières', 'Une onde avance à 2 m/s et se répète toutes les 0,5 s. Pendant cette durée elle avance de 2 × 0,5 = 1 m : λ = 1 m.'),
      b.exemple('Changer de milieu', 'À fréquence imposée de 100 Hz, si la célérité passe de 20 à 10 m/s, λ passe de 20/100 = 0,2 m à 10/100 = 0,1 m. La fréquence reste celle de la source.'),
      b.piege('Sur un graphe en fonction du temps, l’écart entre crêtes donne T ; sur une image en fonction de la position, il donne λ.'),
      ondeQuestion(4, 'ONDE-PER', 'Avec c = 12 m/s et f = 4 Hz, quelle longueur d’onde ?', ['3 m', '48 m', '0,33 m'], 'Pendant une période T = 1/4 s, l’onde parcourt cT = 12/4 = 3 m.'),
      b.recap(['λ : longueur ; T : durée.', 'λ = c/f.', 'La source impose la fréquence.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L5', 'La diffraction par une fente', 4, [
      b.texte('Nous allons prévoir l’élargissement d’une onde après une ouverture. La diffraction apparaît dans le sujet ESATIC 2024 consulté.'),
      b.texte('La **diffraction** est l’étalement d’une onde après une ouverture ou près d’un obstacle. Elle est particulièrement marquée quand la largeur a de l’ouverture est comparable à λ. Pour un laser, la tache centrale est encadrée par deux zones sombres, les premiers **minima**.'),
      b.formule('Petit angle : θ ≈ λ/a ; largeur centrale L ≈ 2Dλ/a.', 'D : distance fente-écran, D très grand devant a ; θ : demi-angle en radians ; toutes les longueurs dans la même unité.'),
      b.texte('Le radian est une unité d’angle : un tour vaut 2π radians, avec π ≈ 3,14. Aux petits angles, la demi-largeur sur l’écran est environ Dθ ; la largeur entière vaut donc 2Dθ.'),
      b.exemple('Une tache centrale', 'λ = 0,0000006 m, a = 0,0001 m, D = 2 m. Alors L ≈ 2 × 2 × 0,0000006/0,0001 = 0,024 m = 2,4 cm.'),
      b.piege('θ décrit la demi-largeur angulaire : oublier le facteur 2 donne seulement la moitié de la largeur centrale. Diffraction et réfraction (changement de direction à une interface) sont différentes.'),
      ondeQuestion(5, 'ONDE-DIFF', 'À λ et D fixes, si la fente est deux fois plus étroite, la tache centrale…', ['Est deux fois plus large', 'Est deux fois plus étroite', 'Ne change pas'], 'L est proportionnelle à 1/a. Diviser a par 2 multiplie L par 2.'),
      b.recap(['Une ouverture étroite peut étaler l’onde.', 'À petits angles : L ≈ 2Dλ/a.', 'Largeur de fente et largeur de tache évoluent en sens inverse.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L6', 'Lire une tension sinusoïdale', 4, [
      b.texte('Nous allons reconnaître les paramètres d’une oscillation régulière. Ils décrivent une tension qui change de signe périodiquement.'),
      b.texte('Une **sinusoïde** est une courbe périodique lisse. Pour une tension centrée sur zéro, son **amplitude** Umax est sa valeur maximale positive ; son minimum est −Umax. Une tension **alternative** change de signe.'),
      b.formule('u(t) = Umax cos(ωt + φ) ; ω = 2πf = 2π/T.', 'ω : pulsation en rad/s ; φ : phase initiale en radians ; cos désigne la fonction cosinus.'),
      b.texte('Le cosinus se lit sur un cercle : cos 0 = 1, cos(π/2) = 0, cos π = −1, cos(2π) = 1. La phase ωt + φ indique l’avancement dans le cycle. Pour φ = 0, le signal commence au maximum.'),
      b.exemple('u(t) = 3 cos(100πt), en V', 'Umax = 3 V. Comparer 100π à 2πf donne f = 50 Hz, donc T = 0,02 s. À t = 0, u = 3 V ; à T/4, u = 0 ; à T/2, u = −3 V.'),
      b.piege('La valeur crête à crête vaut 2Umax pour cette sinusoïde centrée. L’amplitude ne vaut donc pas tout l’écart entre minimum et maximum.'),
      ondeQuestion(6, 'ONDE-PER', 'Une sinusoïde centrée sur zéro va de −4 V à +4 V. Son amplitude est…', ['4 V', '8 V', '0 V'], 'L’amplitude est l’écart maximal à la valeur moyenne nulle : 4 V. Les 8 V représentent la valeur crête à crête.'),
      b.recap(['Amplitude : écart maximal à la moyenne.', 'ω = 2πf.', 'Phase : position dans le cycle.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L7', 'L’échange d’énergie entre C et L', 4, [
      b.texte('Nous allons comprendre pourquoi un condensateur relié à une bobine peut osciller. PC-ELEC a introduit q = Cu et l’énergie d’un condensateur.'),
      b.texte('Une **bobine** est un enroulement conducteur. Son **inductance** L, mesurée en henrys (H), caractérise son opposition aux variations du courant. Elle peut stocker de l’énergie magnétique. Ici la lettre L désigne l’inductance, sans lien avec la largeur de tache de L5.'),
      b.formule('Énergie électrique = ½Cu² ; énergie magnétique = ½Li².', 'C en F, u en V, L en H, i en A : énergies en J.'),
      b.exemple('Début d’une oscillation LC idéale', 'Un condensateur chargé est relié à une bobine idéale sans résistance et sans générateur. Au départ i = 0 : l’énergie est électrique. Il se décharge et le courant grandit : une partie de l’énergie devient magnétique.'),
      b.exemple('Le passage par u = 0', 'Quand u = 0, l’énergie du condensateur est nulle et l’énergie magnétique est maximale. Le courant ne s’arrête pas immédiatement : il recharge ensuite le condensateur avec la polarité opposée.'),
      b.retenir('Dans un circuit LC idéal isolé, l’énergie totale ½Cu² + ½Li² est constante. Les deux formes d’énergie alternent.'),
      ondeQuestion(7, 'ONDE-LC', 'Quand l’énergie magnétique est maximale dans un LC idéal, la tension du condensateur est…', ['Nulle', 'Toujours maximale', 'Nécessairement positive'], 'L’énergie totale est conservée. Si toute cette énergie est magnétique, ½Cu² = 0, donc u = 0.'),
      b.recap(['C stocke une énergie électrique.', 'L stocke une énergie magnétique.', 'LC idéal : échange sans perte.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L8', 'La période propre d’un circuit LC', 4, [
      b.texte('Nous allons calculer la durée d’une oscillation électrique libre. « Libre » signifie que le circuit évolue après l’excitation initiale, sans générateur qui lui impose un rythme.'),
      b.formule('T₀ = 2π√(LC) ; f₀ = 1/T₀.', 'T₀ : période propre ; L en H, C en F ; √ est la racine carrée positive.'),
      b.texte('On admet cette loi du circuit LC idéal. La période dépend de L et C, pas de l’amplitude initiale dans ce modèle linéaire. Si LC est multiplié par 4, sa racine est multipliée par 2 et T₀ aussi.'),
      b.exemple('Une conversion complète', 'L = 10 mH = 0,01 H et C = 1 µF = 0,000001 F. LC = 0,00000001 ; √(LC) = 0,0001. Donc T₀ ≈ 6,283 × 0,0001 = 0,0006283 s = 0,6283 ms.'),
      b.exemple('Modifier la capacité', 'Si C devient quatre fois plus grande, avec L fixe, T₀ double et f₀ est divisée par deux.'),
      b.piege('Ne pas oublier la racine. Le produit LC seul n’est pas une durée : c’est T₀/(2π) au carré.'),
      ondeQuestion(8, 'ONDE-LC', 'Si L est multipliée par 9 à C fixe, T₀ est multipliée par…', ['3', '9', '81'], 'T₀ est proportionnelle à √L. Comme √9 = 3, la période est multipliée par 3.'),
      b.recap(['T₀ = 2π√(LC).', 'Préfixes : convertir avant de calculer.', 'f₀ est l’inverse de T₀.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L9', 'Pourquoi une oscillation s’amortit', 4, [
      b.texte('Nous allons expliquer la diminution des oscillations dans un circuit réel. Une résistance transforme une partie de l’énergie électrique en chaleur.'),
      b.texte('Un circuit **RLC** contient une résistance R, une inductance L et une capacité C. Sans générateur, l’énergie stockée diminue par effet Joule dans R. Une oscillation **amortie** a des maxima de plus en plus petits.'),
      b.exemple('Faible amortissement', 'Une suite de maxima de même signe de 5 V, 4 V, puis 3,2 V signale un amortissement. Le circuit oscille encore : on parle de régime **pseudo-périodique**, car le motif n’est pas exactement répété à amplitude égale.'),
      b.texte('Avec une résistance suffisamment grande, le retour à l’équilibre peut se faire sans oscillation : régime **apériodique**. La frontière est le régime critique. La nature du régime dépend de R, L et C.'),
      b.retenir('Un circuit RC se charge ou se décharge sans échange magnétique ; un LC idéal échange sans perte ; un RLC réel peut osciller en perdant de l’énergie.'),
      b.piege('Le mot RLC ne garantit pas des oscillations. Et une pseudo-période n’est pas exactement la période propre du LC idéal ; elles sont proches si l’amortissement est faible.'),
      ondeQuestion(9, 'ONDE-RLC', 'Dans un RLC libre, pourquoi l’énergie stockée diminue-t-elle ?', ['La résistance dissipe de l’énergie en chaleur', 'La capacité devient forcément nulle', 'La bobine détruit les charges'], 'Le courant traverse une résistance et produit un effet Joule. L’énergie stockée dans C et L est progressivement transférée en chaleur.'),
      b.recap(['Résistance : pertes par effet Joule.', 'Faible amortissement : oscillations décroissantes.', 'Fort amortissement : retour possible sans oscillation.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L10', 'Oscillations forcées et résonance', 4, [
      b.texte('Nous allons distinguer le rythme naturel d’un circuit du rythme imposé par un générateur. Cela permet de comprendre la résonance.'),
      b.texte('Un générateur alternatif alimente un RLC série à une fréquence f choisie. Après le régime de démarrage, le **régime forcé établi** oscille à cette fréquence. Si on varie f à amplitude de tension fixe, l’amplitude du courant varie.'),
      b.retenir('Dans le modèle RLC série idéal avec résistance constante, l’amplitude du courant est maximale à f₀ = 1/(2π√(LC)). Ce maximum est la **résonance d’intensité**.'),
      b.exemple('Balayer la fréquence', 'Pour un circuit dont f₀ = 1 000 Hz, un générateur peut imposer 800 Hz ou 1 200 Hz. Le courant suit chaque fréquence imposée. Son amplitude est la plus grande quand la fréquence atteint 1 000 Hz, à tension fixée.'),
      b.exemple('Le rôle de la résistance', 'Une résistance plus élevée limite davantage le courant et rend le pic de résonance moins marqué. La résonance n’implique donc pas un courant infini dans ce modèle avec R > 0.'),
      b.piege('Cette formule décrit la résonance du courant d’un RLC série. Les maxima de tension de chaque composant ne se déduisent pas automatiquement de cette phrase.'),
      ondeQuestion(10, 'ONDE-RLC', 'Un générateur impose 500 Hz à un circuit dont f₀ = 600 Hz. En régime forcé établi, la fréquence du courant vaut…', ['500 Hz', '600 Hz', '1 100 Hz'], 'Le générateur impose le rythme du régime forcé établi : 500 Hz. f₀ indique la résonance et le rythme propre, pas la fréquence forcée.'),
      b.recap(['Libre : rythme propre après excitation initiale.', 'Forcé établi : rythme du générateur.', 'RLC série : maximum du courant à f₀.']),
    ]),
    lecon('ESATIC-BAC-ONDES-L11', 'Calculer le courant à la résonance', 4, [
      b.texte('Nous allons mesurer l’opposition globale d’un RLC série au courant alternatif. Cela permet de calculer le courant maximal lors d’un balayage en fréquence.'),
      b.texte('La **valeur efficace** d’un courant alternatif est celle du courant continu qui produirait la même puissance moyenne dans une résistance. Pour une sinusoïde, Ieff = Imax/√2 et Ueff = Umax/√2, avec √2 ≈ 1,414. Il faut distinguer amplitude et valeur efficace.'),
      b.formule('Impédance Z = Ueff/Ieff ; Ieff = Ueff/Z.', 'Z en ohms ; elle exprime l’opposition globale du circuit en régime sinusoïdal établi.'),
      b.texte('L’impédance dépend généralement de la fréquence. À la résonance d’intensité du RLC série idéal, les effets de L et C se compensent : Z = R. Le courant efficace atteint donc Ueff/R à tension efficace fixée.'),
      b.exemple('Une valeur de courant', 'Avec Ueff = 12 V et R = 30 Ω, à la résonance : Ieff = 12/30 = 0,4 A. L’amplitude vaut Imax = √2 × 0,4 ≈ 0,566 A. Hors résonance, Z est plus grande et le courant plus faible.'),
      b.piege('Ueff/Imax ne donne pas Z : associer les deux valeurs efficaces, ou les deux amplitudes. Une simple mesure à l’ohmmètre ne donne pas l’impédance d’un circuit à toute fréquence.'),
      ondeQuestion(11, 'ONDE-RLC', 'À la résonance d’intensité d’un RLC série idéal, Z vaut…', ['R', 'Toujours zéro même avec R > 0', 'La capacité C en farads'], 'Les effets de la bobine et du condensateur se compensent à la résonance d’intensité. Il reste l’opposition résistive R, donc Z = R.'),
      b.recap(['Sinusoïde : valeur efficace = amplitude/√2.', 'Ieff = Ueff/Z.', 'À la résonance série : Z = R.']),
    ]),
  ],
  exercices: [
    classer({ ...ondeSpec('ONDE-PROP'), code: 'ESATIC-BAC-ONDES-E01', niveau: 1, consigne: 'Classe les ondes selon le besoin d’un milieu matériel.', categories: ['Onde mécanique', 'Onde électromagnétique'], cartes: [['Son dans l’air', 0], ['Bosse sur une corde', 0], ['Lumière d’un laser', 1]], explication: 'Le son est une compression du milieu et la bosse une déformation de la corde : ces deux ondes sont mécaniques. La lumière est électromagnétique et peut traverser le vide.' }),
    numerique({ ...ondeSpec('ONDE-PROP'), code: 'ESATIC-BAC-ONDES-E02', niveau: 1, consigne: 'Deux points sont distants de 3 m sur une corde. Une perturbation avance à 6 m/s. Quel retard entre les points ?', valeur: 0.5, unite: 's', explication: 'Le retard est la durée du trajet entre les deux points : Δt = d/c = 3/6 = 0,5 s.' }),
    numerique({ ...ondeSpec('ONDE-PER'), code: 'ESATIC-BAC-ONDES-E03', niveau: 1, consigne: 'Un signal a pour période 5 ms. Calcule sa fréquence.', valeur: 200, unite: 'Hz', explication: '5 ms = 0,005 s. La fréquence compte les cycles par seconde : f = 1/0,005 = 200 Hz.' }),
    numerique({ ...ondeSpec('ONDE-PER'), code: 'ESATIC-BAC-ONDES-E04', niveau: 1, consigne: 'Une onde de fréquence 10 Hz avance à 2 m/s. Calcule sa longueur d’onde.', valeur: 0.2, unite: 'm', explication: 'La période vaut 1/10 = 0,1 s. Pendant cette période, l’onde avance de 2 × 0,1 = 0,2 m. On retrouve λ = c/f = 0,2 m.' }),
    qcm({ ...ondeSpec('ONDE-PER'), code: 'ESATIC-BAC-ONDES-E05', niveau: 1, consigne: 'Une tension sinusoïdale centrée sur zéro varie de −6 V à +6 V. Quelle est son amplitude ?', options: ['6 V', '12 V', '0 V'], bonne: 0, explication: 'L’amplitude est l’écart maximal à la moyenne nulle : 6 V. La différence entre les deux extrêmes, 12 V, est la valeur crête à crête.' }),
    numerique({ ...ondeSpec('ONDE-PROP'), code: 'ESATIC-BAC-ONDES-E06', niveau: 2, consigne: 'Un écho revient 0,4 s après l’émission. Avec c = 340 m/s, à quelle distance se trouve l’obstacle ?', valeur: 68, unite: 'm', explication: 'Le son parcourt 340 × 0,4 = 136 m au total. Ce trajet comporte l’aller et le retour, donc la distance de l’obstacle est 136/2 = 68 m.' }),
    qcm({ ...ondeSpec('ONDE-DIFF'), code: 'ESATIC-BAC-ONDES-E07', niveau: 2, consigne: 'Une lumière de longueur d’onde λ traverse une fente de largeur a. L’écran est à D, très grand devant a. À petits angles, quelle est la largeur de la tache centrale ?', options: ['2Dλ/a', 'Dλ/a', '2Da/λ'], bonne: 0, source: { type: 'annale', organisme: 'ESATIC', annee: 2024, epreuve: 'Physique, Q24 (adaptation du schéma de diffraction)', documentId: '6ac01ecf36d8963a0a88c481' }, explication: '(ESATIC 2024, physique, Q24) Le premier minimum correspond au demi-angle θ ≈ λ/a. Sur l’écran, la demi-largeur vaut environ Dθ. La largeur entre les deux premiers minima est donc L ≈ 2Dθ = 2Dλ/a.' }),
    numerique({ ...ondeSpec('ONDE-PER'), code: 'ESATIC-BAC-ONDES-E08', niveau: 2, consigne: 'u(t) = 3 cos(100πt), t en secondes. Quelle est sa fréquence ?', valeur: 50, unite: 'Hz', explication: 'Le coefficient du temps est la pulsation ω = 100π rad/s. Comme ω = 2πf, on divise par 2π : f = 100π/(2π) = 50 Hz.' }),
    qcm({ ...ondeSpec('ONDE-LC'), code: 'ESATIC-BAC-ONDES-E09', niveau: 2, consigne: 'Dans un LC idéal isolé, à l’instant où u = 0 et où l’énergie totale est non nulle, où se trouve l’énergie stockée ?', options: ['Dans la bobine', 'Dans le condensateur seulement', 'Elle a entièrement disparu'], bonne: 0, explication: 'L’énergie électrique vaut ½Cu² = 0. L’énergie totale est conservée et non nulle : elle est donc entièrement magnétique, dans la bobine, sous la forme ½Li².' }),
    vf({ ...ondeSpec('ONDE-RLC'), code: 'ESATIC-BAC-ONDES-E10', niveau: 2, consigne: 'Juge les affirmations sur un RLC libre réel.', affirmations: [['La résistance peut amortir les oscillations.', true], ['Tout RLC oscille forcément.', false], ['Le régime pseudo-périodique conserve exactement la même amplitude.', false]], explication: 'La résistance dissipe de l’énergie en chaleur : elle amortit. Si l’amortissement est suffisamment fort, le retour peut être apériodique, sans oscillation. En régime pseudo-périodique, les maxima diminuent : l’amplitude n’est pas conservée.' }),
    numerique({ ...ondeSpec('ONDE-DIFF'), code: 'ESATIC-BAC-ONDES-E11', niveau: 3, consigne: 'λ = 600 nm, a = 0,10 mm et D = 2 m. Avec L ≈ 2Dλ/a, calcule la largeur centrale en cm. 1 nm = 0,000000001 m.', valeur: 2.4, unite: 'cm', explication: 'Convertir : λ = 0,0000006 m et a = 0,0001 m. L = 2 × 2 × 0,0000006/0,0001 = 0,024 m. Comme 1 m = 100 cm, L = 2,4 cm.' }),
    numerique({ ...ondeSpec('ONDE-LC'), code: 'ESATIC-BAC-ONDES-E12', niveau: 3, consigne: 'Pour L = 10 mH et C = 1 µF, calcule T₀ en ms au millième. Prends 2π ≈ 6,283185.', valeur: 0.628, tolerance: { type: 'abs', valeur: 0.0005 }, decimales: 3, unite: 'ms', explication: 'L = 0,01 H et C = 0,000001 F. LC = 0,00000001 et sa racine vaut 0,0001. T₀ = 6,283185 × 0,0001 = 0,0006283185 s = 0,6283185 ms, soit 0,628 ms au millième.' }),
    numerique({ ...ondeSpec('ONDE-LC'), code: 'ESATIC-BAC-ONDES-E13', niveau: 3, consigne: 'Un LC idéal isolé contient C = 100 µF initialement chargé sous 10 V et L = 10 mH. Le courant initial est nul. Calcule le courant maximal.', valeur: 1, unite: 'A', explication: 'Au départ, l’énergie vaut ½CU² = 0,5 × 0,0001 × 100 = 0,005 J. Au courant maximal, elle vaut ½LImax² = 0,5 × 0,01 × Imax². Égaler donne 0,005 = 0,005 × Imax², donc Imax² = 1 et Imax = 1 A.' }),
    qcm({ ...ondeSpec('ONDE-RLC'), code: 'ESATIC-BAC-ONDES-E14', niveau: 3, consigne: 'À la résonance d’intensité d’un RLC série idéal, quelle proposition est correcte ?', options: ['L’impédance vaut R', 'L’intensité est minimale à tension fixée', 'La fréquence de résonance dépend de R'], bonne: 0, source: { type: 'annale', organisme: 'ESATIC', annee: 2023, epreuve: 'Physique, Q18 (adaptation)', documentId: '6ac01eca36d8963a0a88c47a' }, explication: '(ESATIC 2023, physique, Q18) Les effets de L et C se compensent à la résonance série : l’impédance vaut R, sa valeur minimale. À tension fixée, Ieff = Ueff/Z est donc maximal. La fréquence f₀ = 1/(2π√(LC)) ne dépend pas de R dans ce modèle.' }),
    numerique({ ...ondeSpec('ONDE-RLC'), code: 'ESATIC-BAC-ONDES-E15', niveau: 3, consigne: 'Un générateur sinusoïdal d’amplitude 12√2 V alimente un RLC série idéal à la résonance d’intensité, avec R = 30 Ω. Quel est le courant efficace ?', valeur: 0.4, unite: 'A', explication: 'La tension efficace vaut Ueff = Umax/√2 = 12√2/√2 = 12 V. À la résonance série, Z = R = 30 Ω. Donc Ieff = Ueff/Z = 12/30 = 0,4 A.', indice: 'Convertis l’amplitude en valeur efficace avant d’appliquer Ieff = Ueff/Z.' }),
  ],
};

module.exports = [mecanique, ondes];
